/// "Got ideas? We're listening" — the in-app survey entry at the bottom of Home.
/// Redesign: a solid white card with the shared Home soft shadow (matching the
/// other Home cards), the paper mascot on the left and a chevron on the right.
/// Text colours are fixed for a white surface (no [studyThemeOnBg]) since the
/// content now sits on the card, not on the themed background.
class GotIdeasBanner extends StatelessWidget {
  const GotIdeasBanner({super.key, this.onTap});

  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      label: context.l10n.home.inAppSurveyEntrySemantics,
      child: GestureDetector(
        onTap: onTap == null
            ? null
            : () {
                AppHaptic.select();
                onTap!();
              },
        child: Container(
          margin: EdgeInsets.symmetric(horizontal: 20.w),
          padding: EdgeInsets.symmetric(horizontal: 16.w, vertical: 14.h),
          decoration: BoxDecoration(
            color: AppCustomColor.backgroundWhite,
            borderRadius: BorderRadius.circular(18.r),
            boxShadow: _homeCardShadow,
          ),
          child: Row(
            children: [
              SvgPicture.string(
                _kPaperPlaneSvg,
                width: 54.w,
                fit: BoxFit.contain,
              ),
              12.horizontalSpace,
              Expanded(
                child: RichText(
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  text: TextSpan(
                    children: [
                      TextSpan(
                        text: context.l10n.home.inAppSurveyEntryTitle,
                        style: AppStyle.textBold14.copyWith(
                          color: const Color(0xFFB5860F),
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      TextSpan(
                        text: ' ${context.l10n.home.inAppSurveyEntrySubtitle}',
                        style: AppStyle.text14.copyWith(
                          color: const Color(0xFF8E96C4),
                          fontWeight: FontWeight.w400,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              8.horizontalSpace,
              Icon(
                Icons.chevron_right_rounded,
                color: const Color(0xFFF0C34F),
                size: 20.w,
              ),
            ],
          ),
        ),
      ),
    );
  }
}
